<script lang="ts">
 import {onMount,tick} from 'svelte'
 const uid=$props.id()
 let mounted=$state(false),ariaDisabled=$state(true),busy=$state(false),message=$state(''),active=$state(0),loading=$state(false),chosen=$state(['Maya']),text=$state('Retained tab edit')
 const labels=['Overview','Details']
 onMount(()=>{mounted=true})
 async function key(e:KeyboardEvent,i:number){let next=i;if(e.key==='ArrowRight')next=(i+1)%2;else if(e.key==='ArrowLeft')next=(i+1)%2;else if(e.key==='Home')next=0;else if(e.key==='End')next=1;else return;e.preventDefault();await tick();document.getElementById(`${uid}-tab-${next}`)?.focus()}
 function submit(e:SubmitEvent){e.preventDefault();message=JSON.stringify(Object.fromEntries(new FormData(e.currentTarget as HTMLFormElement)))}
</script>
<section class="task-study" data-study="controls" aria-label="Component contracts"><fieldset disabled={!mounted}><legend class="study-sr">Contract specimens</legend>
<h4>Separate actions</h4><div class="study-actions"><button class="btn" onclick={()=>message='Primary local draft saved.'}>Save local draft</button><details><summary>Other draft actions</summary><button class="btn" onclick={()=>message='Local draft duplicated; save was not executed.'}>Duplicate draft</button></details></div>
<h4>Manual tabs with a delayed panel</h4><div role="tablist" aria-label="Local views">{#each labels as label,i}<button id={`${uid}-tab-${i}`} class="btn" role="tab" tabindex={active===i?0:-1} aria-selected={active===i} aria-controls={`${uid}-panel-${i}`} onkeydown={e=>key(e,i)} onclick={()=>{active=i;loading=i===1}}>{label}</button>{/each}</div>{#each labels as label,i}<div id={`${uid}-panel-${i}`} role="tabpanel" aria-labelledby={`${uid}-tab-${i}`} hidden={active!==i} tabindex="0">{#if i===0}<p>Arrows move focus; Enter or Space activates.</p><label class="study-field">Overview edit<input class="input" bind:value={text}/></label>{:else if loading}<p>Details pending. The task remains usable.</p><button class="btn" onclick={()=>loading=false}>Resolve delayed panel</button>{:else}<p>Details loaded locally.</p>{/if}</div>{/each}
<h4>Multiple values and grouped navigation</h4><div class="study-actions">{#each ['Maya','Eli','Noor'] as name}<label class="check"><input class="checkbox" type="checkbox" value={name} bind:group={chosen}/>{name}</label>{/each}</div><ul>{#each chosen as name}<li>{name}<button class="btn" onclick={async()=>{chosen=chosen.filter(n=>n!==name);message=`Removed ${name}.`;await tick();document.getElementById(`${uid}-choices`)?.focus()}}>Remove {name}</button></li>{/each}</ul><button id={`${uid}-choices`} class="btn" onclick={()=>message=`${chosen.length} selected.`}>Review selected people</button><details><summary>Related guidance</summary><a href="/components/selection">Selection guidance</a></details><p>This grouped navigation uses disclosure and links; it is not a tree widget.</p>
<h4>Read-only, disabled and busy</h4><form onsubmit={submit}><label class="study-field">Read-only reference<input class="input" name="reference" value="REF-024" readonly/></label><label class="study-field">Disabled reference<input class="input" name="disabled" value="EXCLUDED" disabled/></label><label class="check"><input class="checkbox" type="checkbox" bind:checked={ariaDisabled}/> Mark local operation ARIA-disabled</label><button class="btn" type="button" aria-disabled={ariaDisabled||busy} onclick={()=>{if(ariaDisabled||busy)return;busy=true;message='Operation pending; activate Resolve to finish.'}}>Run local operation</button><button class="btn" type="button" disabled={!busy} onclick={()=>{busy=false;message='Operation completed.'}}>Resolve operation</button><button class="btn" type="submit">Inspect submitted fields</button></form><p>The read-only value is submitted; native disabled is excluded. ARIA-disabled requires explicit event suppression. Busy is not a success state.</p>
<article><h4><a href="/components/data-display">Readable card example</a></h4><p>Select and copy this content independently of its actions.</p><button class="btn" onclick={()=>message='Card secondary action used; no navigation.'}>Pin card locally</button></article><p role="status">{message}</p></fieldset><noscript>Contracts remain readable; local operations require JavaScript.</noscript></section>
